import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import "../styles/UserGig.css"; // optional, if you want to style it

const UserGig = () => {
  const { gigId } = useParams();
  const [gig, setGig] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const response = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        setGig(response.data);
      } catch (err) {
        setError("Gig not found or server error");
      } finally {
        setLoading(false);
      }
    };

    fetchGig();
  }, [gigId]);

  if (loading) return <div style={{ textAlign: "center", marginTop: "50px" }}>Loading...</div>;
  if (error) return <div style={{ textAlign: "center", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", border: "1px solid #eee", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
      <h2 style={{ color: "#f97316", marginBottom: "20px" }}>Gig Posting</h2>
      <p><strong>Title:</strong> {gig.title}</p>
      <p><strong>Gig Type:</strong> {gig.gigType}</p>
      <p><strong>Genre:</strong> {Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre}</p>
      <p><strong>City:</strong> {gig.city}</p>
      <p><strong>Description:</strong> {gig.description}</p>
      <p><strong>Posted By:</strong> {gig.username}</p>
      <p><strong>Expires:</strong> {gig.expiryDate?.split("T")[0]}</p>
    </div>
  );
};

export default UserGig;
